#!/usr/bin/env python3
"""Build the static pages. Python standard library only; run from any directory."""
from pathlib import Path
import json,html,re
ROOT=Path(__file__).resolve().parents[1]
F=json.loads((ROOT/'assets/features.json').read_text())
LABEL={'working':'Working on prototype','validation':'Under validation','planned':'Planned','exploring':'Exploring'}
WAIT='https://forms.gle/H6SiFKKwsqFf7kAG9'
def template(n):return (ROOT/'templates'/f'{n}.html').read_text()
def button(label,url,ghost=False):return f'<a class="btn{" ghost" if ghost else ""}" href="{url}">{label}</a>'
def intro(kicker,title,description,actions=''):
 return f'<section class="page-hero"><div class="inner"><span class="eyebrow">{kicker}</span><h1>{title}</h1><p class="hero-sub">{description}</p><div>{actions}</div></div></section>'
def media():return '''<figure class="video-frame"><video class="walkthrough" autoplay muted loop playsinline controls preload="metadata" poster="assets/media/preview.webp" aria-label="Zaman interface preview using fictional games"><source src="assets/media/preview.mp4" type="video/mp4">Your browser cannot play this video. <a href="demo.html">Try the interactive demo.</a></video><figcaption>Interface preview · sample library · simulated gameplay. Interactive demonstration; not footage of the device.</figcaption><button class="video-toggle" type="button">Pause preview</button></figure>'''
def teaser():return '<section id="software" class="software-section"><div class="inner split"><div><span class="eyebrow">A console experience, taking shape</span><h2>Meet Zaman OS.</h2><p class="lead">Your games up front. Your system one button away.</p><p>Browse with a controller, open the system menu, send games from your phone and discover native games through Dukkan. Working today on our development hardware.</p><ul class="tick-list"><li>Your game library, with collections and favorites</li><li>System menu, audio and connection settings</li><li>Streamlined transfers and artwork lookup</li><li>Launch games, Dukkan and Steam from one place</li></ul><div class="actions">'+button('Explore Zaman OS →','os.html')+button('Try it in your browser','demo.html',True)+'</div><p class="small">Open-source software · development prototype</p></div>'+media()+'</div></section>'
def roadmap(full=False):
 cards=''
 for f in F:
  if not full and f['status'] not in ['planned','validation']:continue
  if not full and f['title'] not in ['Stress testing and recovery','Raspberry Pi 5 image','Packaged Zaman component updates','Screenshots and a gallery']:continue
  link=button('Try this →','demo.html?scene='+f['demo'],True) if f.get('demo') else ''
  if f.get('source'):link+=f'<a class="text-link" href="{f["source"]}">Source & implementation ↗</a>'
  if f.get('help'):link+='<a class="text-link" href="contribute.html#opportunities">Help build this →</a>'
  cards+=f'<article class="roadmap-card" data-status="{f["status"]}"><div class="card-meta"><span>{f["group"]}</span><span class="status {f["status"]}">{LABEL[f["status"]]}</span></div><h3>{html.escape(f["title"])}</h3><p>{html.escape(f["detail"])}</p><div class="card-links">{link}</div></article>'
 return '<div class="roadmap-grid">'+cards+'</div>'
def page(name,title,desc,body):
 nav=''.join(f'<li><a href="{file}"'+(' aria-current="page" class="active"' if name==file else '')+f'>{label}</a></li>' for label,file in [('Home','index.html'),('Hardware','hardware.html'),('Pricing','pricing.html'),('Zaman OS','os.html'),('Dukkan','dukkan.html'),('Development','development.html'),('Contribute','contribute.html'),('Downloads','downloads.html')])
 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Zaman · Kawn Electro</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta name="theme-color" content="#100c06"><meta property="og:title" content="{title} | Zaman"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:type" content="website"><link rel="icon" href="assets/bird.webp"><link rel="stylesheet" href="assets/site.css"><script defer src="assets/site.js"></script></head><body><a class="skip-link" href="#main">Skip to content</a><header class="topbar"><a class="brand" href="index.html" aria-label="Zaman home"><img src="assets/wordmark.webp" alt="Zaman"></a><ul class="nav" id="nav">{nav}</ul><a class="nav-cta" href="demo.html">Try the demo ↗</a><button class="menu-btn" id="menuBtn" aria-expanded="false" aria-controls="nav">Menu</button></header><main id="main">{body}</main><footer class="site-footer"><div class="inner footer-grid"><div class="footer-identity"><a href="index.html" class="footer-brand"><img src="assets/bird.webp" alt=""><span>ZAMAN <small lang="ar" dir="rtl">زمان</small></span></a><p>Play. Explore. Belong.</p><p class="footer-description">A modular gaming project by Kawn Electro.<br>Built in Saudi Arabia.</p></div><nav aria-label="Explore Zaman"><h2>Explore</h2><a href="hardware.html">The hardware</a><a href="pricing.html">Target pricing</a><a href="os.html">Zaman OS</a><a href="dukkan.html">Dukkan</a></nav><nav aria-label="Get involved"><h2>Get involved</h2><a href="demo.html">Try Zaman OS ↗</a><a href="development.html">Development roadmap</a><a href="contribute.html">Contribute</a><a href="downloads.html">Images & hardware</a></nav><nav aria-label="About Kawn"><h2>Stay connected</h2><a href="lab.html">The lab & contact</a><a href="https://github.com/citrineio/Zaman">Website source ↗</a><a href="https://www.instagram.com/zaman.console">Instagram ↗</a></nav></div><div class="inner footer-bottom"><span>© 2026 Kawn Electro</span><span>Hardware in development · Specifications and prices are targets</span></div></footer><dialog id="lightbox" aria-label="Image preview"><button class="close-lightbox" aria-label="Close image preview">×</button><img id="lightboxImg" alt=""></dialog></body></html>'''
 out=re.sub(r'(<a\b[^>]*href="demo\.html(?:\?[^"]*)?")',r'\1 target="_blank" rel="noopener noreferrer" title="Opens the interactive preview in a new tab"',out)
 (ROOT/name).write_text(out)

home=template('home')+teaser()+'''<section><div class="inner"><span class="eyebrow">One idea. Three ways to play.</span><div class="intro-grid"><div><h2>Keep what you love.<br>Upgrade what ages.</h2><p>The Core holds the compute. The Wing makes it handheld. The Nest brings it to your TV. Zaman’s hardware is in development, with repair and future upgrades at the heart of the design.</p>'''+button('Explore the hardware','hardware.html',True)+'''</div><div class="hardware-pair"><figure><img src="assets/Zaman_Wing.webp" alt="Zaman Wing handheld concept" loading="lazy"><figcaption><b>Wing</b><span>Take your games with you.</span></figcaption></figure><figure><img src="assets/Zaman_Nest.webp" alt="Zaman Nest TV dock concept" loading="lazy"><figcaption><b>Nest</b><span>Make room for big-screen play.</span></figcaption></figure></div></div></div></section><section class="band"><div class="inner split"><div><span class="eyebrow">Built in the open</span><h2>Play it. Test it.<br>Help shape it.</h2><p>Watch the software evolve, try the browser preview or help bring the experience to more hardware.</p></div><div>'''+button('See development progress','development.html')+button('Build with us','contribute.html',True)+button('Follow the device',WAIT,True)+'''</div></div></section>'''
page('index.html','A gaming experience worth keeping','Explore Zaman, a modular retro gaming project, and try the open-source Zaman OS browser preview.',home)
page('hardware.html','The modular hardware','Explore the Core, Wing and Nest: Zaman’s modular hardware concept, preliminary specifications and target pricing.',intro('The device · In development','One Core.<br>More ways to play.','A swappable compute module, a handheld body and a TV dock. Explore the hardware we are developing around Zaman OS.',button('Follow development',WAIT)+button('See the working software','os.html',True))+template('schematic')+template('why')+template('system')+template('specs')+'<section class="band"><div class="inner"><h2>Find your configuration.</h2><p>Explore the target prices for handheld, TV and full-system bundles.</p>'+button('Explore pricing →','pricing.html')+'</div></section>')
osbody=intro('Zaman OS · Open-source console software','Your games.<br><span class="accent">Within reach.</span>','A controller-first gaming environment built on Armbian Linux. A familiar library, a system menu one button away, and tools that make getting back to play easier.',button('Experience Zaman OS →','demo.html')+button('Follow image releases','downloads.html',True))
osbody+='''<section class="preview-section"><div class="inner">'''+media()+'''</div></section><section><div class="inner"><span class="eyebrow">Working on the prototype</span><h2>Less setup between you and play.</h2><div class="journey-grid">'''
for no,title,copy,scene in [('01','Find your next game','Browse collections, search your library, mark favorites and pick up a recently played game.','library'),('02','Keep control','Bring up the menu over gameplay. Adjust audio, check notifications, resume or exit.','game'),('03','Build your library','Send a game from another device, choose its destination and retrieve artwork and details.','transfer'),('04','Discover something new','Browse Dukkan’s curated native games and keep exploring while an installation runs.','store')]:
 osbody+=f'<a class="journey" href="demo.html?scene={scene}"><span class="eyebrow">{no} / TRY THE WORKFLOW</span><h3>{title}</h3><p>{copy}</p><span class="text-link">Explore in the demo →</span></a>'
osbody+='''</div><p class="small">The browser preview simulates these interactions with sample data. Prototype acceptance applies to tested games and hardware configurations.</p></div></section><section class="band"><div class="inner split"><div><span class="eyebrow">Experience Zaman OS live</span><h2>Take the controls.</h2><p>Launch a small platform game, open the system menu and try a sample transfer. No installation or account needed.</p>'''+button('Launch interactive preview →','demo.html')+'''</div><a class="screenshot-link" href="demo.html"><img src="assets/media/preview.webp" alt="Preview of the Zaman game library" loading="lazy"><span>Interactive browser simulation ↗</span></a></div></section><section id="foundation"><div class="inner split"><div><span class="eyebrow">Open foundations</span><h2>Linux underneath.<br>Zaman at your fingertips.</h2><p>The current development installation uses <strong>Armbian with Debian 13</strong>. Armbian provides the operating-system foundation and board integration. Zaman brings the library, system UI and the coordination that turns individual applications into a console experience.</p><p>Upstream projects keep their own licenses. Zaman’s components are developed in public; each repository documents its own scope.</p><a class="text-link" href="https://www.armbian.com/">Learn about Armbian ↗</a></div><ol class="stack"><li><b>Your games</b><span>Emulators · native Linux games · tested Steam integration</span></li><li><b>The Zaman experience</b><span>Pegasus theme · system menu · Dukkan</span></li><li><b>Session & input coordination</b><span>Sessiond · controller handoff · background services</span></li><li><b>The platform</b><span>Armbian / Debian · Sway / Wayland · Linux drivers</span></li></ol></div></section><section><div class="inner"><span class="eyebrow">What comes next</span><h2>A roadmap you can follow.</h2>'''+roadmap()+button('View every feature & status →','development.html',True)+'''</div></section><section class="band"><div class="inner split"><div><span class="eyebrow">Build Zaman with us</span><h2>More hands.<br>More possibilities.</h2><p>Port to another board, improve a workflow, reproduce a bug or help harden the system.</p></div><div>'''+button('Find your contribution →','contribute.html')+button('Supported & planned hardware','downloads.html',True)+'''</div></div></section>'''
page('os.html','Zaman OS — Play. Explore. Belong.','Explore the Armbian-based Zaman OS, achieved features, development roadmap and interactive browser demo.',osbody)
progress=intro('Development log · Updated 21 October 2026','Working software.<br>Open progress.','The Sprint 7 prototype baseline is accepted. The current priority is rigorous testing and fixing reproduced bugs. Future features follow that hardening work.',button('Try the experience','demo.html')+button('Help test & improve','contribute.html',True))
progress+='''<section class="status-summary"><div class="inner"><p><strong>Working</strong> means accepted on specific prototype paths. <strong>Under validation</strong> needs broader testing. <strong>Planned</strong> is agreed future work. <strong>Exploring</strong> has unresolved feasibility or scope. These are development states, not release dates.</p><p class="small">Sources: current public component repositories and the accepted Sprint 7 closeout, 19 October 2026. The browser demo is illustrative and does not establish platform compatibility.</p><div class="filters" role="group" aria-label="Filter roadmap"><button data-filter="all" aria-pressed="true">All features</button>'''
progress+=''.join(f'<button data-filter="{s}" aria-pressed="false">{label}</button>' for s,label in LABEL.items())
progress+='</div><p id="filter-count" class="small" aria-live="polite"></p>'+roadmap(True)+'''</div></section>'''+template('progress')+'''<section><div class="inner"><span class="eyebrow">Development checkpoints</span><div class="milestones"><article><b>Foundation</b><p>Accelerated graphics, library, controllers and managed sessions on Dragon Q6A.</p></article><article><b>Sprints 4–6</b><p>system menu polish, notifications, background store transactions and Steam library integration.</p></article><article><b>Sprint 7 · Accepted 19 October</b><p>Background game transfer, artwork workflows, consistent menu behavior and ROM library refresh.</p></article><article><b>Now</b><p>Reliability testing, reproduced bug fixes and preparation for reproducible releases.</p></article></div></div></section>'''
page('development.html','Development & roadmap','A transparent roadmap of achieved, validating, planned and exploratory Zaman OS features.',progress)
contrib=intro('For developers, testers & makers','Build Zaman<br>with us.','Help make a console experience that people can understand, repair and improve. Code, testing, documentation and hardware validation all matter.',button('Explore the components','#components')+button('See contribution opportunities','#opportunities',True))
contrib+='''<section id="opportunities"><div class="inner"><span class="eyebrow">Choose your starting point</span><div class="journey-grid"><article class="journey"><h2>Bring your hardware.</h2><p>Help port the shared software to a board you own. Document graphics, audio, controllers, game launching and recovery as separate milestones.</p><a class="text-link" href="https://github.com/citrineio/zaman-sessiond/issues/new?title=Hardware%20port%20proposal">Propose a port ↗</a></article><article class="journey"><h2>Make it dependable.</h2><p>Reproduce controller handoff, transfer interruption and session-recovery bugs. Include the board, component commit, exact steps and relevant logs.</p><a class="text-link" href="https://github.com/citrineio/zaman-sessiond/issues">Browse session issues ↗</a></article><article class="journey"><h2>Improve the experience.</h2><p>Build a focused menu, library or store improvement. Describe the player journey and discuss substantial changes before implementation.</p><a class="text-link" href="https://github.com/citrineio/zaman-menu/issues">Discuss a menu feature ↗</a></article><article class="journey"><h2>Help others get started.</h2><p>Improve setup instructions, record compatibility results, clarify controller guides or help make the experience accessible.</p><a class="text-link" href="https://github.com/citrineio/zaman-pegasus/issues">Improve the library & docs ↗</a></article></div></div></section><section id="components" class="band"><div class="inner"><span class="eyebrow">Four components. One experience.</span><h2>Find your part of the system.</h2><div class="repo-grid">'''
for repo,title,copy in [('zaman-sessiond','Sessiond','Rust session supervision, launch contracts, focus/input coordination and integration helpers.'),('zaman-menu','Zaman Menu','Quickshell / QML system UI, settings, transfer, artwork and notifications.'),('zaman-pegasus','Pegasus theme','Qt Quick library, home, favorites, search, game details and preferences.'),('dukkan','Dukkan','Qt Quick / C++ curated native-game storefront and background transactions.')]:
 contrib+=f'<article><h3>{title}</h3><p>{copy}</p><a href="https://github.com/citrineio/{repo}">Repository & setup ↗</a><a href="https://github.com/citrineio/{repo}/issues">Issues ↗</a></article>'
contrib+='''</div></div></section><section><div class="inner split"><div><span class="eyebrow">A practical first contribution</span><h2>Start small.<br>Leave it better.</h2><ol class="steps"><li>Try the browser demo to understand the intended interaction.</li><li>Read the relevant repository’s README and development instructions.</li><li>Choose a small issue or open a focused proposal with an expected outcome.</li><li>Test the affected journey and document your hardware and results.</li><li>Submit a pull request with the change, validation and remaining limits.</li></ol></div><div class="notice"><h3>About hardware ports</h3><p>Dragon Q6A is the reference development platform. A Raspberry Pi 5 image is planned. Other boards begin as community ports.</p><p>Desktop UI work can often start with component previews. A complete port also needs real-device graphics, input, audio, session and recovery testing.</p><p>Read each repository’s license. Upstream dependencies, fonts and branding retain their own terms.</p>'''+button('Hardware & image status','downloads.html',True)+'''</div></div></section>'''
page('contribute.html','Contribute to Zaman OS','Help port Zaman OS, add features, improve documentation and harden the open-source gaming environment.',contrib)
downloads=intro('Images & hardware','Choose your<br>starting point.','Zaman OS is currently a development installation. Public flashable images are being prepared; there are no image downloads on this page yet.',button('Get development updates',WAIT)+button('Try without installing','demo.html',True))
downloads+='''<section><div class="inner"><div class="hardware-status"><article><span class="status working">Reference development platform</span><h2>Dragon Q6A</h2><p class="lead">QCS6490</p><p>The current Kawn development and acceptance platform. The software experience is working on the configured prototype; a reproducible public image remains to be released.</p><a class="text-link" href="development.html">See the validated scope →</a></article><article><span class="status planned">Planned preview image</span><h2>Raspberry Pi 5</h2><p class="lead">A second way to experience Zaman</p><p>A Kawn-maintained image is planned. Board-specific graphics, audio, controllers, emulator behavior and recovery will be qualified before release.</p><a class="text-link" href="contribute.html">Help prepare the port →</a></article></div><div class="notice"><h3>What an image release will include</h3><p>A board-specific image, checksum and verification instructions, installation guide, tested controller and game matrix, release notes, known limitations, source references and a recovery procedure.</p><p>Support labels describe Kawn’s validation and maintenance. They do not imply endorsement by a board vendor. Features and game performance will vary between platforms.</p></div></div></section>'''
page('downloads.html','Images & supported hardware','Track Zaman OS image availability for Dragon Q6A and the planned Raspberry Pi 5 preview.',downloads)
page('lab.html','The lab & contact','Meet Kawn Electro and Kadhem, the engineer behind Zaman.',intro('The people behind the project','A small lab.<br>A long-term idea.','Independent hardware engineering in Saudi Arabia, with an open approach to building the Zaman experience.')+template('lab')+template('contact'))
page('pricing.html','Pricing & configurations','Explore target pricing for Zaman handheld, TV and complete system configurations.',intro('Pricing · Development targets','Choose your<br>way to play.','Start with the Core and the body that suits you. These are development targets, not final prices or a preorder offer.',button('Explore the hardware','hardware.html',True))+template('pricing'))
dukkan=intro('Dukkan · دكان · Native Linux games','Find your next<br>favorite.', 'A controller-operated storefront for curated native Linux games. Discover, install and return to play from inside the Zaman experience.',button('Try Dukkan in the demo →','demo.html?scene=store')+button('Bring your game to Zaman','#game-developers',True))
dukkan+='<section class="dukkan-intro"><div class="inner split"><figure class="dukkan-mark"><img src="assets/dukkan-shopfront.webp" alt="Dukkan retro toy shop logo"><figcaption>دكان · A little shop for new adventures.</figcaption></figure><div><span class="eyebrow">Made for the controller</span><h2>Browse. Discover.<br>Keep playing.</h2><p>Dukkan brings game discovery, descriptions, screenshots and installation into the console interface. Browse a curated catalog, check your library and follow progress in Activity.</p><ul class="tick-list"><li>Discover and Library views, with search</li><li>Game details, screenshots and a full-screen gallery</li><li>Installations continue while you browse or close the store</li><li>Completed installs appear in the Zaman game library</li><li>Uninstalling keeps application saves</li></ul></div></div></section><section class="band"><div class="inner split"><div><span class="eyebrow">Working prototype</span><h2>Native games.<br>A familiar console flow.</h2><p>The current prototype installs a curated selection of ARM64 Flatpak games through Flathub, with launch and library integration supplied by Zaman. Each game needs its own compatibility and controller testing.</p><p>Dukkan is an early open-source prototype. It currently has no payment system or publisher upload portal.</p>'+button('Explore the store preview →','demo.html?scene=store')+'</div><a class="dukkan-preview" href="demo.html?scene=store"><img src="assets/demo/ember.svg" alt="Fictional Ember Trail game artwork"><span>Try a sample installation in your browser →</span><small>Fictional sample game · simulated installation</small></a></div></section><section id="game-developers"><div class="inner"><span class="eyebrow">For game developers & publishers</span><h2>Bring your game to Zaman.</h2><p class="lead">Help grow a catalog made for playing with a controller.</p><p>Share your project, Linux or ARM64 availability, controller support and distribution license. An existing Flatpak or Flathub package helps; games without one are welcome as integration enquiries.</p><div class="actions">'+button('Submit your game ↗','https://github.com/citrineio/dukkan/issues/new?template=game-submission.yml')+button('Contact Kawn Electro','mailto:kadhem.alabdulmuhsin@kawnelectro.com',True)+'</div><p class="small">A submission starts a conversation. Compatibility, catalog inclusion and commercial arrangements require separate review.</p></div></section><section class="band"><div class="inner split"><div><span class="eyebrow">Open-source development</span><h2>Help build<br>the little shop.</h2><p>Improve controller navigation, expand game testing, refine the catalog or harden the installation and recovery workflows.</p></div><div>'+button('Explore Dukkan source ↗','https://github.com/citrineio/dukkan')+button('Find an issue ↗','https://github.com/citrineio/dukkan/issues',True)+'</div></div></section>'
page('dukkan.html','Dukkan — Native games for Zaman','Discover Dukkan, the controller-operated native Linux game storefront for Zaman. Try the preview, submit a game or contribute.',dukkan)
print('Built 9 content pages plus the interactive demo.')
